
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_pbe_vwn_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_pbe_vwn", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-6.464416414463078e-02, -6.360277623166620e-02, -6.210956016837754e-02, -5.997148048066377e-02, -5.691678431319330e-02, -5.256962863421862e-02, -4.643499210840111e-02, -3.796454317179441e-02, -2.701159772957768e-02, -1.559330642341891e-02, -1.118177537497669e-02, -3.818175511043337e-02, -4.627416470392474e-02, -3.205309032719606e-02, -1.597656394774850e-02, -3.727719008308551e-03, -2.073204600386657e-04, -1.892799672571769e-06, -1.873364226635003e-09, -7.030293622633443e-14]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


